package com.tastenest.servlet;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import com.tastenest.util.DB;
@WebServlet("/login") public class AuthServlet extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json");String email=req.getParameter("email"),pass=req.getParameter("password"),role=req.getParameter("role");try{DB.init();if("ADMIN".equals(role)){if("admin@tastenest.com".equalsIgnoreCase(email)&&"admin123".equals(pass)){req.getSession().setAttribute("role","ADMIN");res.getWriter().print("{\"ok\":true,\"role\":\"ADMIN\"}");}else fail(res,"Invalid admin login");return;}try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("SELECT id,name,email FROM users WHERE email=? AND password=? AND role='CUSTOMER'")){p.setString(1,email);p.setString(2,pass);try(ResultSet r=p.executeQuery()){if(r.next()){HttpSession s=req.getSession();s.setAttribute("userId",r.getInt(1));s.setAttribute("userName",r.getString(2));s.setAttribute("userEmail",r.getString(3));s.setAttribute("role","CUSTOMER");res.getWriter().print("{\"ok\":true,\"role\":\"CUSTOMER\",\"name\":\""+esc(r.getString(2))+"\"}");}else fail(res,"Invalid email or password");}}}catch(Exception e){res.setStatus(500);fail(res,"Database error");}}private void fail(HttpServletResponse r,String m)throws IOException{r.getWriter().print("{\"ok\":false,\"error\":\""+esc(m)+"\"}");}private String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\"","\\\"");}}
